"""Full carrot methods and their recovered sauce components."""
import pathlib,json,sqlite3,copy
root=pathlib.Path(__file__).parent
out=root.parent.parent/'outputs/SavorShelf-Content-Repairs'
db=sqlite3.connect(out/'grouped-work.sqlite3')
rows=json.loads((out/'carrot-candidates.json').read_text(encoding='utf-8'))
rows.append(dict(id='historical-9d97eef8d8dc7dec33d9ceb7'))
records={r['sourceId']:r for r in json.loads((root/'content-overrides.json').read_text(encoding='utf-8'))}
aliases={r['id']:r for r in json.loads((root/'recipe-aliases.json').read_text(encoding='utf-8'))}
newids=[]
def src(n):return json.loads(db.execute('select record from recipes where id=?',(rows[n]['id'],)).fetchone()[0])
def I(k,a,u,n,s):return dict(key=k,amount=a,unit=u,name=n,substitution=s)
def carrot(a):return I('carrot',a,'g','carrots, peeled and trimmed','Use the same weight of a different carrot variety; color and sweetness will change.')
def butter(a):return I('butter',a,'g','unsalted butter','Use the same weight of a block-style dairy-free butter alternative.')
def stock(a):return I('stock',a,'ml','unsalted prepared beef stock','Use the same volume of unsalted vegetable stock for a different flavor; check other ingredients before treating the whole recipe as vegetarian.')
def onion(a):return I('onion',a,'g','peeled onion','Use the same weight of trimmed leek, rinsing away any grit.')
def salt(a=3):return I('salt',a,'g','fine salt','Reduce or omit, especially if using salted stock.')
def pepper():return I('pepper',.25,'tsp','ground black pepper','Use the same amount of ground white pepper, or omit.')
def cayenne():return I('cayenne',.125,'tsp','ground cayenne pepper','Omit for a milder soup.')
def sugar(a):return I('sugar',a,'g','granulated sugar','Use the same weight of caster sugar.')
def water(a,k='water'):return I(k,a,'ml','drinking water','Use the same volume of drinking water; water for dough or starch slurry should remain cold.')
def flour(a):return I('flour',a,'g','all-purpose flour','For a sauce, use the same weight of a gluten-free blend labeled for sauces; pastry requires a separate tested gluten-free dough.')
def bread(a):return I('bread',a,'g','plain bread','Use the same weight of gluten-free bread suitable for toasting.')
def oil(a,k='oil'):return I(k,a,'ml','neutral vegetable oil','Use the same volume of refined sunflower or rapeseed oil.')
def yolks(a):return I('yolks',a,'','large pasteurized egg yolks','Use 18 g pasteurized liquid yolk per large yolk; omitting yolk changes the recipe.')
def cream(a):return I('cream',a,'ml','heavy cream','Use the same volume of unsweetened plant cream suitable for cooking.')
def celery(a):return I('celery',a,'g','trimmed celery stalks','Use the same weight of peeled celeriac, cut small and cooked until tender.')
def turnip(a):return I('turnip',a,'g','peeled turnip','Use the same weight of peeled rutabaga; allow extra cooking time until tender.')
def add(n,title,y,t,desc,items,steps,notes,category='Side dishes'):
 s=src(n);r=copy.deepcopy(s['recipe']);r.update(title=title,description=desc,category=category,servings=y,yieldUnit='servings',minutes=t,totalMinutes=t,ingredients=items,steps=steps,sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T18:00:00Z',notes=notes+' Missing amounts, yields and timings are modern adaptation estimates, not recovered historical measurements. Not kitchen-tested. Scaling changes quantities, not cooking times. Cool leftovers promptly in shallow containers and refrigerate within 2 hours at 4°C (40°F) or colder.',source=s['recipe']['source']+' SavorShelf measured adaptation.');r.pop('variants',None);r['sourceAliases']=[]
 records[r['id']]=dict(sourceId=r['id'],bodySha256=s['bodySha256'],recipe=r);newids.append(r['id']);return r
def variant(r,id,label,items,steps):r.setdefault('variants',[]).append(dict(id=id,label=label,ingredients=items,steps=steps))
PUREE='Press the vegetables and their liquid through a coarse sieve into a clean saucepan, or use an immersion blender directly in the deep pan with its head submerged. Do not seal hot soup in a countertop blender.'
def parsley(a=5):return I('parsley',a,'g','fresh parsley, finely chopped','Use the same weight of chives, or omit.')
def milk(a):return I('milk',a,'ml','whole milk','Use the same volume of unsweetened soy milk; flavor differs.')
def rice(a):return I('rice',a,'g','uncooked long-grain white rice','Use the same weight of another white rice; follow its cooking time until tender.')
def eggfinish():return ['Whisk {{yolks}} with {{cream}} in a bowl. Gradually whisk in a little hot soup, then return the mixture to the saucepan.','Stir over low heat until the soup reaches 71°C (160°F), without boiling. Serve promptly.']
def lemon(a,k='lemon'):return I(k,a,'ml','lemon juice','Use the same volume of lime juice for a different flavor.')
def bay():return I('bay',1,'','dried bay leaf','Omit if unavailable.')
def lard(a):return I('lard',a,'g','food-grade pork lard','Use the same weight of neutral vegetable oil.')
def tk(k):return '{{'+k+'}}'
def roux(prefix,b,f,liquid,liquidname='unsalted prepared chicken stock'):
 return [dict(butter(b),key=prefix+'butter'),dict(flour(f),key=prefix+'flour'),I(prefix+'stock',liquid,'ml',liquidname,'Use the same volume of unsalted vegetable stock; flavor differs.')]
def rouxsteps(p):
 return ['In a separate small saucepan, melt '+tk(p+'butter')+'. Stir in '+tk(p+'flour')+' and cook for 2 minutes without browning. Gradually whisk in '+tk(p+'stock')+' until smooth. Simmer gently for 5 minutes, stirring.']
def veloute(prefix='s',volume=120):
 # A small complete mushroom sauce component, with all output used in its parent.
 q=volume/120
 return roux(prefix,10*q,8*q,120*q)+[I(prefix+'mushroom',25*q,'g','cultivated white mushrooms, finely chopped','Use the same weight of cultivated cremini mushrooms.')]
def veloutesteps(p='s'):
 return ['Melt '+tk(p+'butter')+' in a small pan. Add '+tk(p+'mushroom')+' and cook gently for 5 minutes without browning. Stir in '+tk(p+'flour')+' for 2 minutes, then gradually whisk in '+tk(p+'stock')+'. Simmer for 10 minutes, stirring, until smooth. Press through a fine sieve, discard the mushroom pieces and keep the sauce warm.']

def peas(a):return I('peas',a,'g','shelled green peas, fresh or frozen','Use the same weight of frozen peas, adding them without thawing.')
def cornflour(a):return I('cornflour',a,'g','cornstarch (cornflour)','Use the same weight of arrowroot starch, adding it near the end and heating just until thickened.')
def nutmeg():return I('nutmeg',.125,'tsp','ground nutmeg','Use the same amount of ground mace, or omit.')
def boilsteps(shape='1 cm cubes',time='12–18'):
 return ['Cut {{carrot}} into '+shape+'. Bring {{water}} and {{salt}} to a boil. Add the carrots and simmer for '+time+' minutes until tender when pierced with a fork. Drain well.']

r=add(53,'Gulerødder, Stuvede (Carrots in Parsley-Stock Sauce)',4,40,'Small carrot cubes simmer in a smooth butter-and-stock sauce, finished with chopped parsley.',[carrot(600),stock(400),butter(35),flour(25),parsley(5),salt(2),sugar(5)],['Cut {{carrot}} into 1 cm cubes. Melt {{butter}} in a saucepan, stir in {{flour}} and cook for 2 minutes without dark browning.','Gradually whisk in {{stock}} until smooth. Add the carrots, cover loosely and simmer gently for 20–25 minutes, stirring often, until the carrots are tender. Add a little water if the sauce catches or becomes too thick.','Stir in {{parsley}}, {{salt}} and {{sugar}} and heat for 1 minute. Serve hot.'],'The source plateful and ounce-based roux are not treated as a precise modern proportion. A disclosed 600 g carrot batch with 35 g butter, 25 g flour and 400 ml stock gives a spoonable sauce. The optional young-pea combination is retained separately.')
variant(r,'with-peas','Carrots with young peas',copy.deepcopy(r['ingredients'])+[peas(200)],r['steps'][:2]+['Add {{peas}} and simmer for another 5–8 minutes until tender.']+r['steps'][2:])

r=add(56,'Stuvede Grønærter og Gulerødder (Peas and Diced Carrots)',6,35,'Pea-sized carrot dice and green peas are coated in a buttery parsley sauce made with their cooking liquid.',[peas(500),carrot(400),water(450),sugar(5),salt(3),butter(60),flour(20),parsley(10)],['Cut {{carrot}} into 5 mm dice. Put in a saucepan with {{water}}, {{sugar}} and {{salt}}. Bring to a simmer, cover and cook for 8–10 minutes until nearly tender.','Add {{peas}} and simmer for 5–8 minutes until both vegetables are tender. Drain into a bowl, reserving all the cooking liquid.','Melt {{butter}} in a clean saucepan. Stir in {{flour}} and cook for 2 minutes until pale golden. Gradually whisk in the reserved vegetable liquid and simmer for 4–5 minutes, stirring.','Fold in the drained vegetables and {{parsley}}. Heat gently for 2 minutes and serve.'],'The primary book recipe 722 says 3 Fdkr. peas for twelve people, not the extracted 3 dekaliters. This is a deliberately smaller modern six-serving formula with shelled peas weighed directly; it is not a claimed conversion of the old pod measure. Carrots start before the peas to give even tenderness. Flour is cooked pale golden, not dark brown.')
r['source']+=' Primary recipe 722, printed page 170, checked in the book transcription.'

r=add(77,'Carrots and Peas in Light Milk Sauce',6,40,'Cooked carrot cubes and peas are bound with a small amount of flour, butter, milk and reserved carrot broth.',[carrot(300),peas(300),water(1000),flour(16),salt(2),pepper(),sugar(5),butter(28),milk(120),I('carrotwater',120,'ml','reserved carrot cooking water from the steps','Use the same volume of unsalted vegetable stock if necessary.')],['Cut {{carrot}} into 1 cm cubes. Bring {{water}} to a boil, add the carrots and simmer for 12–18 minutes until tender. Lift out with a slotted spoon; measure {{carrotwater}} from the cooking water and set it aside.','Cook {{peas}} in the remaining hot carrot water for 3–5 minutes until tender. Drain. Combine the cooked vegetables in the saucepan.','Mix {{flour}}, {{salt}}, {{pepper}} and {{sugar}} in a small bowl, sprinkle over the vegetables and toss gently. Add {{butter}}, {{milk}} and the measured reserved carrot water.','Simmer gently for 5–7 minutes, stirring carefully, until the flour is cooked and the vegetables are lightly coated. Serve hot.'],'The two pints of prepared vegetables become explicit 300 g weights each, not universal pint-to-weight conversions. The missing pea cooking is included. Milk and butter are the base choice; a stock-and-oil version is supplied separately.')
variant(r,'stock-and-oil','Stock and oil sauce',[dict(i,name='unsalted prepared vegetable stock',substitution='Use the same volume of unsalted chicken stock if desired.') if i['key']=='milk' else dict(i,amount=30,unit='ml',name='neutral vegetable oil',substitution='Use the same volume of refined sunflower oil.') if i['key']=='butter' else copy.deepcopy(i) for i in r['ingredients']],copy.deepcopy(r['steps']))

r=add(81,'Russian-Style Sweet Carrot Compote',6,60,'Carrot dice are browned in butter, simmered in sugar syrup and finished in the oven until lightly golden.',[sugar(200),water(240),carrot(300),butter(28)],['Heat the oven to 200°C (390°F). Cut {{carrot}} into 1 cm cubes. Melt {{butter}} in an oven-safe skillet and cook the carrots for 6–8 minutes, turning, until lightly browned.','Meanwhile, combine {{sugar}} and {{water}} in a saucepan. Bring to a gentle boil and cook for 10 minutes without letting the syrup color or dry out.','Carefully pour the hot syrup over the carrots. Simmer gently for 15–25 minutes until tender. Add a little water if the syrup becomes sticky before the carrots soften.','Transfer the skillet to the oven and bake uncovered for 8–12 minutes until the carrots are lightly browned and glazed. Watch closely to avoid burning the sugar. Let cool for 5 minutes before serving small portions.'],'The source cup of sugar and water become 200 g and 240 ml. Two cups of diced carrots become a chosen 300 g preparation weight. Oven temperature, browning time and portion size are modern choices. This is a sweet compote, not a savory vegetable side.','Desserts')

r=add(83,'Flemish Carrots with Onion and Stock',6,70,'Parboiled carrot slices are tossed with lightly browned onion, then simmered slowly in stock and finished with parsley.',[carrot(600),water(1000),I('boilsalt',6,'g','fine salt for the cooking water','Reduce or omit.'),oil(30),onion(100),sugar(4),salt(1.5),I('pepper',.125,'tsp','ground white pepper','Use the same amount of black pepper.'),stock(360),parsley(2)],['Cut {{carrot}} into 5 mm slices. Bring {{water}} and {{boilsalt}} to a boil and cook the carrots for 10–15 minutes until just tender. Drain.','Heat {{oil}} in a wide saucepan. Add finely chopped {{onion}} and cook for 6–8 minutes until lightly golden. Add the carrots, {{sugar}}, {{salt}} and {{pepper}}. Cook gently for 10 minutes, shaking the pan or turning carefully.','Add {{stock}}, cover loosely and simmer very gently for 30 minutes until the carrots are soft. Uncover briefly if needed to reduce excess liquid. Stir in {{parsley}} and serve.'],'The shorter duplicate stops at the source page break. The complete primary text continues with pepper, ten minutes of tossing, stock, a half-hour simmer and parsley; all are restored. The quart of sliced carrots becomes a chosen 600 g weight. The long stock finish is retained, rather than replacing it with a quick sauté.')
r['source']+=' Complete primary text checked across printed pages 110–111.'

r=add(84,'Lemon Carrots with Paprika and Parsley',4,35,'Tender carrot dice are coated with butter, lemon juice, parsley and a little paprika.',[carrot(350),water(1000),salt(3),parsley(2),sugar(3),I('paprika',.5,'tsp','sweet paprika','Use the same amount of mild smoked paprika for a different flavor.'),butter(14),lemon(15)],boilsteps()+['Return the drained carrots to the warm pan. Add {{parsley}}, {{sugar}}, {{paprika}}, {{butter}} and {{lemon}}.','Warm over low heat for 2–3 minutes, shaking or turning gently until every piece is coated. Serve hot.'],'A pint of prepared carrots becomes a chosen 350 g carrot weight. The grating of loaf sugar becomes 3 g and half a lemon becomes 15 ml juice. Salt in the boiling water is measured; no extra finishing salt is required.')
r=add(85,'Slow-Simmered Sweet Carrot Rounds',6,45,'Carrot rounds cook gently under a lid with butter and sugar, leaving a light glaze as the moisture reduces.',[carrot(600),butter(14),sugar(38),salt(3),water(90)],['Cut {{carrot}} into even 5 mm rounds. Put in a heavy saucepan with {{butter}}, {{sugar}}, {{salt}} and {{water}}.','Cover tightly and cook over low heat for 25–35 minutes, shaking the pan occasionally, until tender. Check regularly and add a small splash of water if the pan becomes dry.','Uncover for the final 2–4 minutes, turning gently, to reduce the liquid to a light glaze. Serve hot.'],'The source omits liquid; a modern 90 ml starting amount prevents scorching before the carrots release moisture. A quart of sliced carrots becomes a chosen 600 g weight, and salt is deliberately moderated to 3 g. Butter is selected from the original butter/drippings choice.')

r=add(87,'Purée z Marchwi (Carrot Purée with Milk)',4,40,'Sieved carrots are simmered with milk and a little flour, then finished with butter and pepper.',[carrot(500),water(1000),milk(240),salt(2),flour(16),butter(5),pepper()],['Cut {{carrot}} into 1 cm pieces. Bring {{water}} to a boil and cook the carrots for 15–20 minutes until very tender. Drain thoroughly and press through a sieve into a saucepan.','Add {{milk|0.75}} and {{salt}} to the purée. Heat gently, stirring. Whisk {{flour}} with {{milk|0.25}} until smooth and stir this slurry into the hot purée.','Simmer gently for 5–7 minutes, stirring constantly, until the flour is cooked and the purée is smooth. Stir in {{butter}} and {{pepper}} and serve.'],'The half-quart of prepared purée is replaced by a disclosed 500 g peeled-carrot starting weight. The source cup of milk becomes 240 ml, with one-quarter reserved cold for the flour slurry. Full carrot cooking is supplied.')
r=add(88,'Sałata z Marchwi with Egg-Yolk Dressing',4,80,'Chilled cooked carrots sit on lettuce with a tangy dressing of hard-cooked egg yolk, butter and vinegar.',[carrot(300),water(1000),water(1000,'freshwater'),I('yolk',1,'','fully hard-cooked large egg yolk, chilled','Use the yolk from a hard-boiled duck egg only if fully cooked; flavor and size differ.'),butter(14),I('vinegar',30,'ml','white wine vinegar','Use the same volume of apple cider vinegar.'),salt(1),pepper(),I('lettuce',60,'g','washed lettuce leaves, dried','Use the same weight of washed romaine leaves.')],['Put {{carrot}} whole in a saucepan with {{water}}. Bring to a simmer and cook for 10–15 minutes, until partly tender. Carefully drain.','Add {{freshwater}} to the carrots, return to a simmer and cook for another 10–20 minutes until tender through the center. Drain, cut into 1 cm pieces and spread in a shallow container. Cool briefly, then refrigerate until cold, about 30 minutes.','Press {{yolk}} through a fine sieve. Mash with softened {{butter}}, then gradually whisk in {{vinegar}}, {{salt}} and {{pepper}} to make a slightly textured dressing.','Line a serving bowl with {{lettuce}}, add the chilled carrots and spoon over the dressing. Serve promptly.'],'The original mid-cook water change is retained. Three carrots become a chosen 300 g weight, and a few tablespoons of vinegar become 30 ml. A fully hard-cooked chilled yolk is an explicit prepared ingredient. The butter dressing may remain slightly textured; no raw egg is used.','Salads')
r=add(89,'Selery z Marchwią (Carrots and Celery in Milk)',6,45,'Equal amounts of carrots and celery cook separately, then warm together in a lightly thickened milk sauce.',[carrot(350),celery(350),water(1000),water(1000,'celerywater'),I('boilsalt',4,'g','fine salt for the vegetable water','Reduce or omit.'),milk(480),cornflour(3),salt(2),pepper(),butter(14)],['Slice {{carrot}} thinly and cut {{celery}} into small cubes. Bring {{water}} and {{boilsalt|0.5}} to a boil in one saucepan, add the carrots and simmer for 10–15 minutes until tender.','In a second saucepan, bring {{celerywater}} and {{boilsalt|0.5}} to a boil. Add the celery and cook for 8–12 minutes until tender. Drain both vegetables thoroughly.','Combine the vegetables in one pan with {{milk|0.9375}}, {{salt}}, {{pepper}} and {{butter}}. Mix {{cornflour}} with {{milk|0.0625}} until smooth and stir into the pan.','Bring gently to a simmer while stirring. Cook for 1–2 minutes until lightly thickened and serve.'],'The source does not specify whether celery is stalk or root; stalk celery is the explicit base interpretation and a celeriac variation is retained. The half-quart becomes a modern 480 ml milk, with 30 ml reserved for the starch slurry. This is a light milk sauce, not a thick béchamel.')
vitems=[dict(i,name='peeled celeriac, cut in 1 cm cubes',substitution='Use the stalk-celery base version for a lighter flavor.') if i['key']=='celery' else copy.deepcopy(i) for i in r['ingredients']]
vsteps=copy.deepcopy(r['steps']);vsteps[1]=vsteps[1].replace('8–12','15–20')
variant(r,'celeriac','Carrots and celeriac',vitems,vsteps)

r=add(93,'Creole Stewed Carrots in Milk Sauce',6,85,'Whole carrots are cooked, sliced and simmered in a light milk sauce with parsley and a little sugar.',[carrot(600),water(1000,'soakwater'),water(1500),salt(3),butter(14),flour(8),milk(360),pepper(),parsley(5),sugar(4)],['Put {{carrot}} in a bowl with {{soakwater}} and leave for 15 minutes, then drain. Bring {{water}} and {{salt}} to a boil in a saucepan. Add the carrots whole and simmer for 25–40 minutes until tender, topping up water if needed.','Drain and cut the carrots into 1 cm dice or thin slices. In a clean pan, melt {{butter}}, stir in {{flour}} and cook for 2 minutes without browning.','Gradually whisk in {{milk}}, add {{pepper}} and simmer for 5 minutes, stirring. Add the carrots and simmer very gently for 20 minutes, stirring occasionally and loosening with a splash of water if needed.','Stir in {{parsley}} and {{sugar}}, heat for 1 minute and serve.'],'The source hour-and-a-half initial boil is shortened to a tenderness check for modern carrots; its separate twenty-minute sauce simmer remains. Three-quarters of a pint becomes a modern 360 ml. Parsley and sugar appear in the source method but not its ingredient list and are now measured.')
r=add(96,'Gulerødder in Parsley White Sauce',4,45,'Cooked carrot pieces are warmed in a simple milk-and-butter sauce with finely minced parsley.',[carrot(500),water(1000),salt(3),butter(25),flour(16),milk(300),parsley(5)],boilsteps('2 cm pieces','18–25')+['Melt {{butter}} in a clean saucepan, stir in {{flour}} and cook for 2 minutes. Gradually whisk in {{milk}} and simmer for 5 minutes until smooth.','Fold in the carrots and {{parsley}} and warm gently for 2 minutes. Serve hot.'],'Undefined large spoonfuls and the amount of milk are replaced by a modern 500 g carrot batch. Carrots are cut before cooking for even tenderness; the source milk-or-cream choice is retained in a named cream version.')
variant(r,'cream','Cream and parsley sauce',[dict(i,name='light cream (about 18% fat)',substitution='Use the milk base for a lighter sauce.') if i['key']=='milk' else copy.deepcopy(i) for i in r['ingredients']],copy.deepcopy(r['steps']))

r=add(112,'Porkkanoita Sipulin Kanssa (Carrots and Onions)',6,40,'Carrots and onions are coated in a light butter sauce made from their reserved cooking broth.',[carrot(600),onion(300),water(1200),salt(3),butter(28),flour(8),I('brothportion',300,'ml','reserved vegetable cooking broth from the steps','Use the same volume of unsalted vegetable stock if needed.')],['Cut {{carrot}} into 1 cm cubes and {{onion}} into small wedges. Bring {{water}} and {{salt}} to a boil. Add both vegetables and simmer for 15–20 minutes until tender.','Drain into a bowl. Measure {{brothportion}} from the reserved liquid; refrigerate unused broth promptly for another use.','Melt {{butter}} in the empty saucepan, stir in {{flour}} and cook for 2 minutes. Gradually whisk in the measured cooking broth and simmer for 5 minutes.','Add the drained vegetables and heat for 2 minutes, turning gently. Serve hot.'],'The source four cups of carrots and three onions become modern 600 g and 300 g weights. Repeated butter/flour entries describe the same sauce rather than additional purchases. The optional mashed-potato presentation is a serving suggestion, not an undeclared ingredient.')
vsteps=['Cut {{carrot}} into 1 cm cubes. Bring {{water}} and {{salt}} to a boil and simmer the carrots for 12–18 minutes until tender. Drain into a bowl, measure {{brothportion}} from the liquid and set it aside.','Melt {{butter}} in a saucepan. Add finely sliced {{onion}} and cook gently for 12–15 minutes until soft. Stir in {{flour}} and cook for 2 minutes.','Gradually whisk in the measured carrot broth and simmer for 5 minutes. Fold in the drained carrots, heat for 2 minutes and serve.']
variant(r,'butter-onions','Butter-softened onions',copy.deepcopy(r['ingredients']),vsteps)
vitems=[dict(i,amount=150,name='white parts of scallions, washed and trimmed',substitution='Use the onion base version instead.') if i['key']=='onion' else copy.deepcopy(i) for i in r['ingredients']]
vsteps=copy.deepcopy(r['steps']);vsteps[0]='Cut {{carrot}} into thin 5 mm strips and {{onion}} into short lengths. Bring {{water}} and {{salt}} to a boil, add both vegetables and simmer for 10–15 minutes until tender.'
variant(r,'scallions','Carrot strips and scallion whites',vitems,vsteps)

r=add(113,'Ruskeutetut Porkkanat (Butter-Browned Carrots)',4,40,'Tender carrot strips are dried carefully and pan-fried in butter until golden on both sides.',[carrot(500),water(1000),salt(3),butter(30)],boilsteps('lengthwise strips about 1 cm thick','12–18')+['Spread the carrots on a clean towel and pat dry. Heat {{butter}} in a wide skillet over medium heat.','Add the carrots in one layer, working in batches if necessary. Brown for 3–4 minutes on each side, turning gently, then serve.'],'Full boiling, cutting and drying instructions replace the prepared-boiled-carrot input. Butter is selected from the source butter/lard choice. The alternative part-cooked diced preparation and optional sugar-lemon finish are supplied together as a named variation.')
variant(r,'lemon-cubes','Lemon-sugar carrot cubes',copy.deepcopy(r['ingredients'])+[sugar(5),lemon(10)],boilsteps('1 cm cubes','6–8')+['Pat the partly cooked carrots dry. Heat {{butter}} in a wide skillet, add the cubes and cook for 10–15 minutes, turning often, until tender and golden.','Add {{sugar}} and {{lemon}} and toss for 1 minute until coated. Serve hot.'])

r=add(137,'Boiled Carrots',6,40,'Carrots are cut evenly and simmered in salted water until tender, then drained and served hot.',[carrot(750),water(2000),salt(8)],['Cut {{carrot}} into similar-sized pieces: halve large carrots across the middle, then quarter them lengthwise. Bring {{water}} and {{salt}} to a boil in a large saucepan.','Add the carrots and simmer for 15–25 minutes, checking with a fork, until tender through the center. Add water if needed to keep them submerged.','Drain thoroughly and serve hot.'],'The source half-gallon and heaped tablespoon are replaced by 2 liters water and a deliberately moderate 8 g salt. Carrot weight is supplied. The matching Indian Cookery Book salted-water method is consolidated with its whole-young-carrot option retained; its one-to-three-hour guidance is replaced by a modern tenderness check.')
variant(r,'whole-young','Whole young carrots',copy.deepcopy(r['ingredients']),['Choose slender young {{carrot}} of similar size and leave them whole. Bring {{water}} and {{salt}} to a boil.','Add the carrots and simmer for 15–30 minutes until a fork enters the center easily; thick carrots may take longer. Keep them submerged with extra water if needed.','Drain and serve hot.'])

r=add(140,'Sliced Carrots with Stock Glaze and Butter',6,45,'Part-cooked carrot slices simmer in sweetened stock until glazed, then are finished with fresh butter.',[carrot(750),water(1500),I('boilsalt',5,'g','fine salt for the boiling water','Reduce or omit.'),sugar(10),stock(570),butter(85),salt(2)],['Cut {{carrot}} into even 5 mm slices. Bring {{water}} and {{boilsalt}} to a boil, add the carrots and cook for 6–8 minutes until half tender. Drain well.','Put the carrots in a wide saucepan with {{sugar}} and {{stock}}. Boil briskly, turning gently, for 12–20 minutes until the carrots are tender and the stock reduces to a syrupy glaze. Watch closely near the end.','Reduce the heat. Add {{butter}} in pieces and {{salt}}, shaking or turning gently until the butter coats the carrots. Serve immediately.'],'The British source pint is rounded to 570 ml and three ounces of butter to 85 g. Five or six large carrots and a lump of sugar become chosen weights. The fresh butter is added after the stock reduction, preserving the source finishing method.')
r=add(141,'Stewed Carrots with Cream and Broth',6,55,'Part-boiled carrots finish gently in cream and broth, with a small butter-flour mixture thickening the sauce.',[carrot(900),water(1500),salt(3),stock(180),cream(90),pepper(),butter(28),flour(12)],boilsteps('1 cm slices','8–10')+['Put the partly cooked carrots in a saucepan with {{stock}}, {{cream}} and {{pepper}}. Cover loosely and simmer gently for 15–20 minutes until tender, turning carefully to avoid breaking them.','Mash softened {{butter}} with {{flour}} to a smooth paste. Stir small pieces of this paste into the simmering carrot sauce.','Simmer gently for 5–7 minutes, stirring carefully, until the flour is cooked and the sauce coats the carrots. Add a little water if needed to loosen. Serve hot.'],'The source teacup and half-teacup become modern choices of 180 ml broth and 90 ml cream, not a universal historical conversion. Seven or eight carrots become 900 g. Cutting before the initial partial boil gives even cooking, and the raw butter-flour paste receives a full simmer.')

r=add(143,'German-Style Carrots in Browned Roux Sauce',6,50,'Carrot rounds braise with parsley, onion and nutmeg, then finish in a lightly browned sauce made from their broth.',[carrot(1000),butter(85),salt(3),nutmeg(),parsley(5),onion(10),stock(650),I('rouxbutter',15,'g','unsalted butter for the roux','Use the same weight of a block-style dairy-free butter alternative.'),flour(8)],['Cut {{carrot}} into 5 mm rounds. Melt {{butter}} in a saucepan, add the carrots, {{salt}}, {{nutmeg}}, {{parsley}} and finely minced {{onion}}, and toss over medium-low heat for 4–5 minutes.','Add {{stock}}, cover loosely and simmer for 15–20 minutes until the carrots are nearly tender. Carefully drain into a bowl, reserving all the broth, and return the carrots to the pan.','In another saucepan, melt {{rouxbutter}}. Stir in {{flour}} and cook, stirring, for 3–4 minutes until light brown. Gradually whisk in the reserved carrot broth until smooth.','Pour the sauce over the carrots and simmer for 5–10 minutes until completely tender. Serve hot.'],'Eight large carrots become a modern 1 kg batch; the slightly-more-than-a-British-pint broth becomes 650 ml. The extra small piece of roux butter is listed separately from the source three ounces used to start the carrots. All broth is reused in the sauce.')
r=add(146,'Gelbe Rüben in Light Roux Sauce',6,55,'Fine carrot strips are cooked from cold water, then simmered in a pale roux sauce made with their cooking broth.',[carrot(750),water(1500),salt(4),I('fat',50,'g','unsalted butter','Use the same weight of food-grade pork lard for the source fat alternative.'),flour(30),I('brothportion',450,'ml','reserved carrot cooking broth from the steps','Use the same volume of unsalted vegetable stock if necessary.')],['Cut {{carrot}} into strips about 5 mm thick. Put in a saucepan with {{water}} and {{salt}}, bring to a simmer and cook for 8–12 minutes until partly tender.','Drain into a bowl and measure {{brothportion}} from the liquid. Keep that broth for the sauce; cool any unused broth promptly for another use.','Melt {{fat}} in a clean saucepan, stir in {{flour}} and cook for 2 minutes without dark browning. Gradually whisk in the measured broth and simmer for 5 minutes.','Fold in the carrots and simmer very gently for 15–20 minutes, turning occasionally, until very tender. Add a little water if the sauce catches. Serve hot.'],'Five dekagrams of fat become 50 g. Flour is required by the source roux but omitted from its ingredient list; 30 g is supplied. Four to six carrots and the broth amount become modern weights/volumes. The initial cook is shortened because fine modern carrot strips would collapse after the source thirty minutes plus twenty-minute finish.')

for n,title,veg in [(147,'Karotten Glasiert (Butter-Glazed Carrots)','carrots'),(154,'Glasierte Rüben (Butter-Glazed Turnips)','turnips')]:
 items=[I('veg',600,'g','peeled '+veg,'Use the same weight of another variety of '+veg+'.'),butter(50),sugar(22),salt(2),water(100)]
 steps=['Cut {{veg}} into even 1 cm pieces. Melt {{butter}} in a heavy saucepan, add {{sugar}} and cook gently, watching closely, until pale golden.','Add the vegetables and {{salt}}, then carefully add {{water}}; the hot sugar may sputter. Cover and simmer over low heat for '+('25–35' if veg=='carrots' else '35–50')+' minutes, shaking the pan occasionally, until tender. Add small splashes of water as needed to prevent scorching.','Uncover and cook for 3–5 minutes, turning gently, until the liquid reduces to a shiny coating. Serve hot.']
 r=add(n,title,4,50 if veg=='carrots' else 65,'Tender '+veg+' are coated in a pale caramel and butter glaze after a gentle covered braise.',items,steps,'The full same-book glazed-turnip method supplies the otherwise missing carrot instructions. Five dekagrams of butter become 50 g; five or six undefined sugar cubes become a chosen 22 g. Vegetable weight and starting water are supplied. Cooking ends at tenderness rather than a fixed hour. The optional flour dusting is unnecessary once the liquid is reduced to a glaze and is omitted.')
 if n==147:r['source']+=' Complete component source: same-book glazed turnips, source ID historical-9d97eef8d8dc7dec33d9ceb7.'

r=add(149,'Sauce aux Carottes (Grated-Carrot Butter Sauce)',8,35,'Finely grated carrots soften in butter and lightly caramelized sugar, then thicken a small stock sauce with parsley and nutmeg.',[butter(112),sugar(13),carrot(300),flour(12),stock(250),parsley(1),nutmeg()],['Melt {{butter}} in a heavy saucepan. Add {{sugar}} and heat gently until the sugar begins to color pale gold; do not let the butter burn.','Add finely grated {{carrot}} and cook gently for 10–15 minutes, stirring, until softened.','Sprinkle in {{flour}}, stir for 2 minutes, then gradually add {{stock}}. Stir in {{parsley}} and {{nutmeg}}.','Bring to a gentle simmer and cook for 5–7 minutes until the flour is cooked and the sauce lightly coats a spoon. Serve in small portions.'],'Eight source tablespoons of butter become 112 g. Two or three carrots become 300 g, and the missing flour amount becomes 12 g. The original quarter-liter stock is retained. Butter is selected from the butter/lard alternative; this is a rich vegetable sauce, not soup.','Sauces')

r=add(7,'Currant and Sultana Suet Pudding',8,180,'A steamed pudding of breadcrumbs, flour and suet is studded with currants and sultanas and flavored with treacle and lemon zest.',[I('breadcrumbs',113,'g','plain dry breadcrumbs','Use the same weight of dry breadcrumbs made from another plain wheat bread.'),I('currants',113,'g','dried currants','Use the same weight of small raisins.'),I('suet',113,'g','finely shredded food-grade beef suet','Use the same weight of shredded vegetable suet intended for steamed puddings; check its label for added flour.'),flour(113),I('sultanas',113,'g','sultanas','Use the same weight of raisins.'),I('treacle',30,'g','black treacle','Use the same weight of golden syrup for a lighter flavor.'),I('zest',1,'g','finely grated unwaxed lemon zest, yellow part only','Use the same weight of finely grated orange zest.'),milk(180),I('grease',5,'g','softened unsalted butter for the basin','Use the same weight of a block-style dairy-free butter alternative.'),water(2000)],['Grease a heatproof 1.2-liter pudding basin with {{grease}}. Put a heatproof trivet in a large lidded saucepan and add {{water}}, adjusting the water level so it will reach halfway up the outside of the basin. Bring the water to a simmer.','Mix {{breadcrumbs}}, {{currants}}, {{suet}}, {{flour}}, {{sultanas}} and {{zest}} in a bowl. Stir {{treacle}} into {{milk}}, then mix into the dry ingredients to make a thick, soft mixture. If still crumbly, add water a teaspoon at a time until it holds together.','Spoon into the basin, leaving at least 3 cm of headroom. Cover with a pleated sheet of baking parchment and a sheet of foil, securing firmly around the rim with kitchen string. Make a string handle for lifting.','Lower the basin onto the trivet. Cover the saucepan and steam over gently simmering water for 2–2½ hours, checking every 30 minutes and topping up with boiling water so the pan never runs dry.','Lift out carefully and remove the cover away from your face. A skewer pushed into the center should come out without raw paste. If needed, re-cover and steam for another 15–20 minutes. Rest for 10 minutes, loosen the edge and turn out. Serve warm.'],'The printed page 214 was visually checked: despite the heading Carrot Pudding, it contains no carrot. The title is corrected to describe the actual ingredients rather than inventing one. The scan gives one-quarter pound EACH of breadcrumbs, currants, suet, flour and sultanas, not the larger extracted amounts. Those weights become 113 g each. Treacle, milk, zest, basin size and a longer doneness-led steaming time are disclosed modern choices.','Desserts')
r['source']+=' Primary scan verified: printed page 214, Internet Archive leaf 238. The original source title remains in the immutable source record.'
next(i for i in r['ingredients'] if i['key']=='flour')['substitution']='Use the same weight of plain wheat pastry flour; this pudding has not been formulated for gluten-free flour.'
r['notes']+=' When increasing the quantity, divide between additional basins with the same headroom rather than overfilling one basin; larger basins need a separate doneness check.'

r=add(97,'Syltede Gulerødder (Lemon Carrot Preserve, Refrigerated)',24,3000,'Fine carrot strips and lemon peel steep in a sweet lemon syrup, which is reduced again after two days of refrigeration.',[carrot(450),I('peel',24,'g','thin yellow lemon peel, without white pith, cut into fine strips','Use the same weight of thin orange peel for a different flavor.'),water(1000),sugar(450),I('carrotwater',240,'ml','reserved carrot cooking water from the steps','Use the same volume of fresh drinking water if needed.'),lemon(60),I('extrasugar',85,'g','granulated sugar for the second syrup cooking','Use the same weight of caster sugar.'),lemon(15,'extralemon')],['Cut {{carrot}} into fine matchsticks about 2–3 mm thick. Put in a saucepan with {{peel}} and {{water}}, bring to a simmer and cook covered for 15–30 minutes, checking frequently, until tender but still intact.','Drain into a bowl. Measure {{carrotwater}} from the cooking liquid. Put that measured liquid in a clean pan with {{sugar}}, bring to a simmer and stir until dissolved.','Add the drained carrots and peel with {{lemon}} and simmer gently for 10 minutes. Transfer to shallow food-safe containers, cool promptly and refrigerate within 2 hours at 4°C (40°F) or colder. Keep refrigerated for 48 hours.','Drain the cold carrots and peel, reserving all the syrup. Put the syrup in a saucepan with {{extrasugar}} and {{extralemon}}. Boil gently for 8–10 minutes until slightly thickened, watching carefully so it does not burn.','Take off the heat and stir in the carrots and peel without boiling them again. Transfer to clean shallow containers, cool promptly and refrigerate within 2 hours. Serve in small spoonfuls. Use within 4 days of the first cooking, including the 48-hour resting period, or freeze promptly.'],'Two primary scans were compared: both say carrots, water, a half-hour initial cook and half a pint of reserved water. The extracted Rødbeder title, vinegar, one-pint water and one-and-a-half-hour cook are transcription errors. A modern 450 g pound and 240 ml half-pint are explicit choices; peel and juice weights are supplied. Cognac-paper covering and room-temperature storage are replaced by refrigeration/freezing. This is not a tested canning recipe and is not shelf-stable. Total time includes the 48-hour refrigerated rest.','Preserves')
r['source']+=' Primary scans visually verified: Skandinavisk-amerikansk kogebog printed page 240 (leaf248); Skandinavisk illustreret kogebog printed page231 (leaf237).'

merges=[(82,83,'The complete primary text continues across printed pages110–111; the shorter record is the same recipe cut off at the page break.'),(66,137,'Both full sources describe carrots boiled in salted water to tenderness. Whole young carrots are retained as a named variation; historical prolonged cooking is replaced by a disclosed modern tenderness check.'),(57,97,'Both original page scans show the same carrot, lemon, sugar and two-stage syrup method, including half-hour cook and half-pint cooking water. Apparent differences in extracted titles, vinegar and fractions are transcription errors.')]
for old,target,reason in merges:
 s=src(old);r=records[rows[target]['id']]['recipe'];r['sourceAliases'].append(s['id']);r['source']+=' Equivalent source retained: '+s['recipe']['source'];aliases[s['id']]=dict(id=s['id'],canonicalId=r['id'],bodySha256=s['bodySha256'],reason=reason)
assert len(newids)==24,len(newids)
(root/'content-overrides.json').write_text(json.dumps(list(records.values()),ensure_ascii=False,indent=2),encoding='utf-8')
(root/'recipe-aliases.json').write_text(json.dumps(list(aliases.values()),ensure_ascii=False,indent=2),encoding='utf-8')
for id in newids:db.execute('insert or replace into decisions values(?,?,?,?,?)',(id,records[id]['bodySha256'],'prepared-adaptation','Full ingredients/method reviewed; primary text and scans used for ambiguities; modern amounts, components and choices disclosed','repair-batch-013.py'))
for old,target,reason in merges:
 id=rows[old]['id'];db.execute('insert or replace into decisions values(?,?,?,?,?)',(id,aliases[id]['bodySha256'],'prepared-merge',reason,'repair-batch-013.py'))
db.commit();print(json.dumps(dict(newAdaptations=len(newids),newMergedSources=len(merges),totalOverrides=len(records),totalAliases=len(aliases))))
